import { flushSync, mount, unmount } from "svelte";
import type { ScanResult, ScannerOptions } from "../../src/core/types";
import {
  createScannerExamples,
  type ScannerDialogExampleName,
  type ScannerExampleName,
} from "../../examples/scanner-examples";
import { createSvelteScannerRuntime, type SvelteScannerRuntime } from "../src/runtime/scanner-runtime";
import App from "./App.svelte";

export interface SvelteSkeletonHooks {
  onScan(result: ScanResult<unknown>): void;
  onAction(detail: { id: string; kind: string }): void;
  onDialogAction(detail: { actionId: string }): void;
}

export interface SvelteSkeletonOptions {
  scannerOptions?: ScannerOptions<unknown>;
  hooks?: Partial<SvelteSkeletonHooks>;
  exampleCode?: string;
  exposeToWindow?: boolean;
}

export interface SvelteSkeletonApp {
  scanner: SvelteScannerRuntime<unknown>;
  examples: ReturnType<typeof createScannerExamples>;
  runExample(name: ScannerExampleName): void;
  showDialog(name: ScannerDialogExampleName): Promise<string>;
  destroy(): void;
}

declare global {
  interface Window {
    qrScanSvelteSkeleton?: SvelteSkeletonApp;
  }
}

const noOp = () => {};

export function mountSvelteSkeleton(host: HTMLElement, options: SvelteSkeletonOptions = {}): SvelteSkeletonApp {
  const scannerOptions = options.scannerOptions ?? {};
  const runtime = createSvelteScannerRuntime<unknown>({
    ...scannerOptions,
    camera: {
      autoStart: true,
      facingMode: "environment",
      idealWidth: 1920,
      idealHeight: 1080,
      allowSwitching: true,
      ...scannerOptions.camera,
    },
  });
  const examples = createScannerExamples(runtime, { code: options.exampleCode });
  const hooks: SvelteSkeletonHooks = {
    onScan: options.hooks?.onScan ?? noOp,
    onAction: options.hooks?.onAction ?? noOp,
    onDialogAction: options.hooks?.onDialogAction ?? noOp,
  };
  runtime.addEventListener("scanresult", (event) => hooks.onScan((event as CustomEvent<ScanResult<unknown>>).detail));
  runtime.addEventListener("action", (event) => hooks.onAction((event as CustomEvent<{ id: string; kind: string }>).detail));
  runtime.addEventListener("dialogaction", (event) => hooks.onDialogAction((event as CustomEvent<{ actionId: string }>).detail));
  runtime.addEventListener("cameraerror", (event) => {
    const { message } = (event as CustomEvent<{ message: string }>).detail;
    runtime.setStatus({ tone: "error", text: `Camera unavailable: ${message}. Use the camera control to retry.` });
  });

  const component = mount(App, { target: host, props: { runtime } });
  flushSync();
  const app: SvelteSkeletonApp = {
    scanner: runtime,
    examples,
    runExample: (name) => examples.states[name](),
    showDialog: (name) => examples.showDialog(name),
    destroy: () => {
      void unmount(component);
      flushSync();
      runtime.destroy();
      if (window.qrScanSvelteSkeleton === app) delete window.qrScanSvelteSkeleton;
    },
  };
  if (options.exposeToWindow !== false) window.qrScanSvelteSkeleton = app;
  return app;
}
